package com.oms.supplychain;
import com.oms.supplychain.service.wms.*;
import com.oms.supplychain.service.warehouse.PurchaseGoodsClient;
import com.ruoyi.common.core.domain.R;
import org.junit.jupiter.api.*;
import org.springframework.test.util.ReflectionTestUtils;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static com.oms.supplychain.PurchaseWorkspaceTest.*;
class WarehouseControlTest {
 WarehouseReconciliation service;WarehouseControlScope scope;QimenWarehouseControlProtocol protocol;StockMovementClient stock;
 @BeforeAll static void start(){PurchaseWorkspaceTest.init();}
 @AfterAll static void stop(){PurchaseWorkspaceTest.shutdown();}
 @BeforeEach void setup(){new PurchaseWorkspaceTest().seed();for(String t:Arrays.asList("warehouse_control_audit","warehouse_control_event","warehouse_transfer_execution","warehouse_transfer_line","warehouse_transfer","warehouse_stock_adjustment","warehouse_inventory_report","warehouse_reconciliation"))db.update("DELETE FROM "+t);protocol=new QimenWarehouseControlProtocol();scope=new WarehouseControlScope();stock=mock(StockMovementClient.class);ReflectionTestUtils.setField(scope,"db",context.getBean(WmsStore.class));ReflectionTestUtils.setField(scope,"stock",stock);ReflectionTestUtils.setField(scope,"connections",context.getBean(WmsConnections.class));ReflectionTestUtils.setField(scope,"goods",context.getBean(PurchaseGoodsClient.class));service=new WarehouseReconciliation();ReflectionTestUtils.setField(service,"db",context.getBean(WmsStore.class));ReflectionTestUtils.setField(service,"scope",scope);ReflectionTestUtils.setField(service,"stock",stock);ReflectionTestUtils.setField(service,"connections",context.getBean(WmsConnections.class));ReflectionTestUtils.setField(service,"protocol",protocol);ReflectionTestUtils.setField(service,"logs",context.getBean(WmsInteractionLog.class));ReflectionTestUtils.setField(service,"work",mock(WarehouseControlWork.class));}
 Map<String,Object>config(){return m("provider","QIMEN","api_version","2.0","app_key","APP","customer_id","OWNER","endpoint","http://localhost/qimen");}
 Map<String,String>params(String method,String body){Map<String,String>p=new TreeMap<>();p.put("method","taobao.qimen."+method);p.put("v","2.0");p.put("sign_method","md5");p.put("app_key","APP");p.put("customerId","OWNER");p.put("timestamp",java.time.LocalDateTime.now(java.time.ZoneId.of("Asia/Shanghai")).format(java.time.format.DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss")));p.put("sign",QimenProtocol.sign(p,body,"SECRET"));return p;}
 Map<String,Object>range(){return m("stores",Arrays.asList("V","V2"),"skus",Collections.singletonList("A"),"batch_code","");}
 Map<String,Object>oms(){return m("batches",Arrays.asList(m("id",1,"sku_sn","A","store_code","V","batch_code","B","zp_actual_number",6,"zp_lock_number",1,"cp_actual_number",0,"cp_lock_number",0,"transaction_price","2.50"),m("id",2,"sku_sn","A","store_code","V2","batch_code","B","zp_actual_number",4,"zp_lock_number",0,"cp_actual_number",0,"cp_lock_number",0,"transaction_price","2.50")));}
 List<Map<String,Object>>wms(long physical,long frozen){return Collections.singletonList(m("sku_sn","A","batch_code","B","inventory_type","ZP","physical",physical,"frozen",frozen,"unfrozen",physical-frozen));}
 Map<String,Object>row(Map<String,Object>r){return ((List<Map<String,Object>>)r.get("rows")).get(0);}
 @Test void physicalWarehouseAggregatesVirtualsOnce(){Map<String,Object>r=service.compare(oms(),wms(10,1),range(),Collections.emptyList());assertEquals("MATCHED",row(r).get("status"));assertEquals(10L,row(r).get("oms_physical"));assertEquals(2,((List)row(r).get("sources")).size());assertEquals(0L,r.get("difference_count"));}
 @Test void differenceShowsExactSignedAmountAndCanApplyOnlyWhenClear(){Map<String,Object>r=service.compare(oms(),wms(8,1),range(),Collections.emptyList());assertEquals(-2L,row(r).get("difference"));assertEquals("PHYSICAL_DIFFERENCE",row(r).get("status"));assertEquals(true,r.get("can_adjust"));}
 @Test void pendingPostingKeepsDifferenceButBlocksAdjustment(){Map<String,Object>r=service.compare(oms(),wms(8,1),range(),Collections.singletonList(m("document_sn","CG123","reason","待入账")));assertEquals(-2L,row(r).get("difference"));assertEquals("WAITING_POST",row(r).get("status"));assertEquals(false,r.get("can_adjust"));}
 @Test void frozenMismatchDoesNotBecomePhysicalLoss(){Map<String,Object>r=service.compare(oms(),wms(10,3),range(),Collections.emptyList());assertEquals("FROZEN_CHECK",row(r).get("status"));assertEquals(0L,r.get("difference_count"));assertEquals(2L,row(r).get("frozen_difference"));assertEquals(false,r.get("can_adjust"));}
 @Test void absentRowsAreUnknownRatherThanZero(){Map<String,Object>r=service.compare(oms(),Collections.emptyList(),range(),Collections.emptyList());assertEquals("MISSING_WMS",row(r).get("status"));assertNull(row(r).get("wms_physical"));assertEquals(false,r.get("can_adjust"));}
 @Test void duplicateChannelRowsCannotDoubleCount(){List<Map<String,Object>>r=new ArrayList<>(wms(10,1));r.addAll(wms(10,1));assertThrows(IllegalArgumentException.class,()->service.compare(oms(),r,range(),Collections.emptyList()));}
 @Test void unsupportedGradeNotSilentlyMappedToBad(){List<Map<String,Object>>r=wms(10,1);r.get(0).put("inventory_type","JS");Map<String,Object>d=service.compare(oms(),r,range(),Collections.emptyList());assertEquals(false,d.get("can_adjust"));assertTrue(((List<Map<String,Object>>)d.get("rows")).stream().anyMatch(x->x.get("status").equals("UNSUPPORTED_TYPE")));}
 @Test void inventoryQueryIncludesRepeatedCriteriaNotSalesOrderLines(){WmsProtocol.Wire w=protocol.wire(config(),"SECRET","inventory.query",m("criteriaList",m("criteria",Arrays.asList(m("itemCode","A"),m("itemCode","B")))));assertTrue(w.body.contains("<criteria><itemCode>A</itemCode></criteria><criteria>"));assertFalse(w.body.contains("orderLine"));}
 @Test void queryPhysicalIncludesFrozenAndMissingNumbersStayUnknown(){String b="<response><flag>success</flag><items><item><warehouseCode>W</warehouseCode><itemCode>A</itemCode><inventoryType>ZP</inventoryType><batchCode>B</batchCode><quantity>8</quantity><lockQuantity>2</lockQuantity></item></items></response>";Map<String,Object>r=protocol.inventory(b,"W","O",false);assertEquals(10L,row(r).get("physical"));assertNull(row(protocol.inventory(b.replace("<lockQuantity>2</lockQuantity>",""),"W","O",false)).get("physical"));assertThrows(IllegalArgumentException.class,()->protocol.inventory(b,"OTHER","O",false));}
 String receipt(){return "<request><deliveryOrder><deliveryOrderCode>DBO12345678901234567890123456789012</deliveryOrderCode><deliveryOrderId>X</deliveryOrderId><orderType>DBCK</orderType><warehouseCode>W</warehouseCode><ownerCode>O</ownerCode><outBizCode>M</outBizCode><status>DELIVERED</status><confirmType>0</confirmType><totalOrderLines>1</totalOrderLines></deliveryOrder><orderLines><orderLine><orderLineNo>1</orderLineNo><itemCode>A</itemCode><batchCode>B</batchCode><inventoryType>ZP</inventoryType><actualQty>2</actualQty></orderLine></orderLines></request>";}
 @Test void signedTransferReceiptBindsTypeMessageAndCompleteLines(){String b=receipt();assertTrue(QimenWarehouseControlProtocol.matches(b));Map<String,Object>r=protocol.receipt(config(),"SECRET",params("stockout.confirm",b),b);assertEquals(true,r.get("complete"));assertEquals(2L,((List<Map<String,Object>>)r.get("lines")).get(0).get("quantity"));String fragment=b.replace("<totalOrderLines>1","<totalOrderLines>2");assertThrows(IllegalArgumentException.class,()->protocol.receipt(config(),"SECRET",params("stockout.confirm",fragment),fragment));}
 @Test void invalidSignatureAndChangedQualityAreRejected(){String b=receipt();assertThrows(IllegalArgumentException.class,()->protocol.receipt(config(),"OTHER",params("stockout.confirm",b),b));String other=b.replace("<inventoryType>ZP","<inventoryType>JS");assertThrows(IllegalArgumentException.class,()->protocol.receipt(config(),"SECRET",params("stockout.confirm",other),other));}
 @Test void qimenEntryCreateUsesDBRKAndRelatedBusinessDocument(){Map<String,Object>e=m("side","IN","document_sn","DBI123","transfer_sn","DB123","create_time","2026-10-26 10:00:00");WmsProtocol.Wire w=protocol.transfer(config(),"SECRET","CREATE",e,m("external_owner","O","external_warehouse","W"),Collections.singletonList(m("line_key",1,"sku_sn","A","goods_name","商品A","inventory_type","ZP","quantity",2,"batch_code","B","unit_cost","2.50","stock_unit","件")));assertTrue(w.body.contains("<orderType>DBRK</orderType>"));assertTrue(w.body.contains("<orderType>DB</orderType><orderCode>DB123"));assertFalse(w.body.contains("sourceOrderCode"));}
 @Test void stockoutUsesDBCKAndLinkedTargetEntry(){Map<String,Object>e=m("side","OUT","document_sn","DBO123","target_entry_sn","DBI123","transfer_sn","DB123","create_time","2026-10-26 10:00:00");WmsProtocol.Wire w=protocol.transfer(config(),"SECRET","CREATE",e,m("external_owner","O","external_warehouse","W","receiver",m("name","收货人")),Collections.emptyList());assertTrue(w.body.contains("<orderType>DBCK</orderType>"));assertTrue(w.body.contains("<targetEntryOrderCode>DBI123"));assertTrue(w.url.contains("stockout.create"));}
 @Test void reportDeltaIsSignedAndNotificationDoesNotCallInventory(){String b="<request><totalPage>1</totalPage><currentPage>1</currentPage><pageSize>1</pageSize><warehouseCode>W</warehouseCode><ownerCode>O</ownerCode><checkOrderCode>CHECK1</checkOrderCode><outBizCode>MSG</outBizCode><adjustType>CHECK</adjustType><items><item><itemCode>A</itemCode><inventoryType>ZP</inventoryType><batchCode>B</batchCode><quantity>-2</quantity><totalQty>8</totalQty></item></items></request>";Map<String,Object>r=protocol.inventoryReport(config(),"SECRET",params("inventory.report",b),b);assertEquals(-2L,((List<Map<String,Object>>)r.get("lines")).get(0).get("delta"));verifyNoInteractions(stock);}
 @Test void pendingAndPagedListsAreReadOnlyAndCompanyScoped(){service.pending("QM",range());assertTrue(service.pending("OTHER",range()).isEmpty());assertEquals(0L,service.list("OTHER",Collections.emptyMap()).get("total"));verifyNoInteractions(stock);}

 @Test void signedReportCallbackBindsConnectionAndPersistsOnceWithoutStockWrites(){
  long connection=context.getBean(WmsConnections.class).save("QM",m("name","TEST盘点通知","provider","QIMEN","api_version","2.0","environment","TEST","endpoint","http://localhost/qimen","app_key","APP","customer_id","OWNER","secret","SECRET","enabled",1));
  db.update("UPDATE wms_simulation_store_info SET connection_id=?,external_owner='O',external_warehouse='W' WHERE company_key='QM' AND wms_simulation_code='V'",connection);
  String key=db.queryForObject("SELECT callback_key FROM wms_connection WHERE id=?",String.class,connection);
  String b="<request><totalPage>1</totalPage><currentPage>1</currentPage><pageSize>1</pageSize><warehouseCode>W</warehouseCode><ownerCode>O</ownerCode><checkOrderCode>CHECK1</checkOrderCode><outBizCode>MSG1</outBizCode><adjustType>CHECK</adjustType><items><item><itemCode>A</itemCode><inventoryType>ZP</inventoryType><batchCode>B</batchCode><quantity>-2</quantity><totalQty>8</totalQty></item></items></request>";
  assertTrue(service.callback("QM",key,params("inventory.report",b),b).contains("<flag>success</flag>"));assertTrue(service.callback("QM",key,params("inventory.report",b),b).contains("<flag>success</flag>"));assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM warehouse_inventory_report",Integer.class));
  String changed=b.replace("<quantity>-2","<quantity>-3");assertTrue(service.callback("QM",key,params("inventory.report",changed),changed).contains("<flag>failure</flag>"));verifyNoInteractions(stock);
 }

 @Test void scanOnlySchedulesBoundedWorkAndDoesNotQueryWarehouseOrInventory(){
  long connection=context.getBean(WmsConnections.class).save("QM",m("name","TEST异步扫描","provider","QIMEN","api_version","2.0","environment","TEST","endpoint","http://localhost/qimen","app_key","APP","customer_id","OWNER","secret","SECRET","enabled",1));db.update("UPDATE wms_simulation_store_info SET connection_id=?,external_owner='O',external_warehouse='W' WHERE company_key='QM' AND wms_simulation_code='V'",connection);
  long id=service.create("QM",m("request_key","SCAN1","store_code","V","skus",Collections.singletonList("A"),"method","inventory.query"),"tester");assertEquals(1,service.scan("QM"));assertEquals("PENDING",db.queryForObject("SELECT state FROM warehouse_reconciliation WHERE id=?",String.class,id));verify((WarehouseControlWork)ReflectionTestUtils.getField(service,"work"),times(2)).ready("QM",id,false);verifyNoInteractions(stock);
 }
}
